#!/usr/bin/env python3
# Generated by runa via A2A Mesh delegation
"""
DLQ Canary Test — before replaying messages from the Dead Letter Queue,
send a single canary (probe) message along the route to validate that
the destination is reachable and the transport is healthy.

If the canary succeeds, the replay proceeds.
If the canary fails, the replay is aborted and the DLQ entries are preserved.

This module is self-contained and runnable from the repo root.
"""

import argparse
import json
import os
import sys
import time
import uuid
import hashlib
import logging
from dataclasses import dataclass, field, asdict
from datetime import datetime, timezone
from enum import Enum
from typing import Any, Optional

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(name)s: %(message)s",
)
logger = logging.getLogger("dlq_canary")


# ---------------------------------------------------------------------------
# Data models
# ---------------------------------------------------------------------------

class DLQEntryStatus(str, Enum):
    PENDING = "pending"
    CANARY_PASSED = "canary_passed"
    CANARY_FAILED = "canary_failed"
    REPLAYED = "replayed"
    REPLAY_FAILED = "replay_failed"
    EXPIRED = "expired"


@dataclass
class DLQEntry:
    """Represents a single dead-lettered message."""
    entry_id: str
    original_message: dict
    target_node: str
    source_node: str
    transport: str
    failure_reason: str
    queued_at: str
    attempts: int = 0
    max_attempts: int = 5
    status: DLQEntryStatus = DLQEntryStatus.PENDING
    last_canary_at: Optional[str] = None
    last_replay_at: Optional[str] = None
    metadata: dict = field(default_factory=dict)

    @classmethod
    def create(cls, message: dict, target_node: str, source_node: str,
               transport: str, failure_reason: str) -> "DLQEntry":
        return cls(
            entry_id=uuid.uuid4().hex[:12],
            original_message=message,
            target_node=target_node,
            source_node=source_node,
            transport=transport,
            failure_reason=failure_reason,
            queued_at=datetime.now(timezone.utc).isoformat(),
        )

    def to_dict(self) -> dict:
        d = asdict(self)
        d["status"] = self.status.value
        return d

    @classmethod
    def from_dict(cls, d: dict) -> "DLQEntry":
        d = dict(d)
        d["status"] = DLQEntryStatus(d.get("status", "pending"))
        return cls(**d)


# ---------------------------------------------------------------------------
# Canary probe
# ---------------------------------------------------------------------------

@dataclass
class CanaryResult:
    success: bool
    latency_ms: float
    error: Optional[str] = None
    response: Optional[dict] = None


class CanaryProbe:
    """
    Sends a lightweight canary message to validate a route before
    committing to a full DLQ replay.
    """

    # Known healthy nodes in the mesh (simulated registry)
    KNOWN_NODES = {
        "tor", "manon", "runa", "kai", "sage",
    }

    def __init__(self, node_registry: Optional[dict] = None,
                 canary_timeout_s: float = 5.0):
        self.node_registry = node_registry or {}
        self.timeout = canary_timeout_s
        # Merge with known defaults
        for node in self.KNOWN_NODES:
            if node not in self.node_registry:
                self.node_registry[node] = {
                    "transport": "websocket",
                    "online": True,
                    "version": "0.4.2",
                }

    def _build_canary_message(self, target_node: str,
                              transport: str) -> dict:
        """Build a minimal probe message."""
        return {
            "type": "canary",
            "id": f"canary-{uuid.uuid4().hex[:8]}",
            "target": target_node,
            "transport": transport,
            "payload": {
                "probe": True,
                "timestamp": datetime.now(timezone.utc).isoformat(),
                "checksum": hashlib.sha256(
                    f"canary:{target_node}:{transport}".encode()
                ).hexdigest()[:16],
            },
            "ttl": 10,
        }

    def send(self, target_node: str, transport: str) -> CanaryResult:
        """
        Send a canary probe to target_node via the given transport.
        Returns a CanaryResult.
        """
        canary_msg = self._build_canary_message(target_node, transport)
        logger.info(
            "Canary probe → node=%s transport=%s id=%s",
            target_node, transport, canary_msg["id"],
        )

        start = time.monotonic()

        # --- Simulated transport check ---
        # In a real mesh, this would dispatch via the transport layer
        # and wait for an ACK. Here we simulate based on the registry.
        node_info = self.node_registry.get(target_node)
        if node_info is None:
            elapsed = (time.monotonic() - start) * 1000
            return CanaryResult(
                success=False,
                latency_ms=elapsed,
                error=f"Unknown node: {target_node}",
            )

        if not node_info.get("online", False):
            elapsed = (time.monotonic() - start) * 1000
            return CanaryResult(
                success=False,
                latency_ms=elapsed,
                error=f"Node {target_node} is offline",
            )

        node_transport = node_info.get("transport", "websocket")
        if transport != node_transport:
            # Transport mismatch — route may not be valid
            elapsed = (time.monotonic() - start) * 1000
            return CanaryResult(
                success=False,
                latency_ms=elapsed,
                error=(
                    f"Transport mismatch: expected '{transport}', "
                    f"node supports '{node_transport}'"
                ),
            )

        # Simulate network latency
        time.sleep(0.05)
        elapsed = (time.monotonic() - start) * 1000

        # Simulate a response ACK
        response = {
            "type": "canary_ack",
            "from": target_node,
            "canary_id": canary_msg["id"],
            "status": "ok",
            "latency_ms": round(elapsed, 2),
        }

        logger.info(
            "Canary ACK ← node=%s latency=%.1fms",
            target_node, elapsed,
        )

        return CanaryResult(
            success=True,
            latency_ms=elapsed,
            response=response,
        )


# ---------------------------------------------------------------------------
# DLQ Manager with canary-gated replay
# ---------------------------------------------------------------------------

class DLQManager:
    """
    Manages the Dead Letter Queue with canary-gated replay.

    Flow:
      1. Messages that fail delivery are enqueued in the DLQ.
      2. On replay, a canary probe is sent first.
      3. If canary passes → replay all matching entries.
      4. If canary fails → abort replay, preserve entries.
    """

    def __init__(self, dlq_path: str = "dlq.json",
                 canary: Optional[CanaryProbe] = None):
        self.dlq_path = dlq_path
        self.canary = canary or CanaryProbe()
        self.entries: list[DLQEntry] = []
        self._load()

    # -- Persistence --

    def _load(self):
        if os.path.exists(self.dlq_path):
            try:
                with open(self.dlq_path, "r", encoding="utf-8") as f:
                    data = json.load(f)
                self.entries = [DLQEntry.from_dict(e) for e in data]
                logger.info("Loaded %d DLQ entries from %s",
                            len(self.entries), self.dlq_path)
            except (json.JSONDecodeError, KeyError, TypeError) as e:
                logger.warning("Could not parse DLQ file: %s — starting fresh", e)
                self.entries = []
        else:
            logger.info("No existing DLQ file at %s — starting fresh", self.dlq_path)

    def _save(self):
        with open(self.dlq_path, "w", encoding="utf-8") as f:
            json.dump([e.to_dict() for e in self.entries], f,
                      indent=2, ensure_ascii=False)
        logger.debug("Saved %d DLQ entries to %s", len(self.entries), self.dlq_path)

    # -- Queue operations --

    def enqueue(self, message: dict, target_node: str, source_node: str,
                transport: str, failure_reason: str) -> DLQEntry:
        entry = DLQEntry.create(
            message=message,
            target_node=target_node,
            source_node=source_node,
            transport=transport,
            failure_reason=failure_reason,
        )
        self.entries.append(entry)
        self._save()
        logger.info(
            "Enqueued DLQ entry %s → %s (reason: %s)",
            entry.entry_id, target_node, failure_reason,
        )
        return entry

    def get_pending(self, target_node: Optional[str] = None) -> list[DLQEntry]:
        pending = [e for e in self.entries
                   if e.status in (DLQEntryStatus.PENDING,
                                   DLQEntryStatus.REPLAY_FAILED)]
        if target_node:
            pending = [e for e in pending if e.target_node == target_node]
        return pending

    # -- Canary-gated replay --

    def replay_with_canary(self, target_node: Optional[str] = None,
                           transport: Optional[str] = None,
                           dry_run: bool = False) -> dict:
        """
        Perform a canary-gated DLQ replay.

        1. Collect pending entries (optionally filtered by target/transport).
        2. Send a single canary probe to the target.
        3. If canary passes, replay all matching entries.
        4. If canary fails, abort and return the failure.

        Returns a summary dict.
        """
        pending = self.get_pending(target_node=target_node)
        if not pending:
            logger.info("No pending DLQ entries to replay.")
            return {
                "canary": None,
                "replayed": 0,
                "failed": 0,
                "skipped": 0,
                "aborted": False,
                "message": "No pending DLQ entries.",
            }

        # Determine the canary target from the first pending entry
        # (all entries in a filtered replay should share the same target)
        first = pending[0]
        canary_target = target_node or first.target_node
        canary_transport = transport or first.transport

        logger.info(
            "=== DLQ Canary-Gated Replay ===\n"
            "  Pending entries: %d\n"
            "  Canary target:   %s\n"
            "  Canary transport: %s\n"
            "  Dry run:         %s",
            len(pending), canary_target, canary_transport, dry_run,
        )

        # Step 1: Send canary
        canary_result = self.canary.send(canary_target, canary_transport)

        if not canary_result.success:
            logger.error(
                "Canary FAILED → aborting replay. Error: %s",
                canary_result.error,
            )
            # Mark entries as canary_failed (but keep them in DLQ)
            for entry in pending:
                entry.status = DLQEntryStatus.CANARY_FAILED
                entry.last_canary_at = datetime.now(timezone.utc).isoformat()
            self._save()
            return {
                "canary": {
                    "success": False,
                    "error": canary_result.error,
                    "latency_ms": canary_result.latency_ms,
                },
                "replayed": 0,
                "failed": 0,
                "skipped": len(pending),
                "aborted": True,
                "message": (
                    f"Canary probe to {canary_target} via {canary_transport} "
                    f"failed: {canary_result.error}. Replay aborted, "
                    f"DLQ entries preserved."
                ),
            }

        logger.info(
            "Canary PASSED (%.1fms) → proceeding with replay of %d entries.",
            canary_result.latency_ms, len(pending),
        )

        # Mark entries as canary_passed
        for entry in pending:
            entry.status = DLQEntryStatus.CANARY_PASSED
            entry.last_canary_at = datetime.now(timezone.utc).isoformat()

        if dry_run:
            logger.info("Dry run — not actually replaying messages.")
            self._save()
            return {
                "canary": {
                    "success": True,
                    "latency_ms": canary_result.latency_ms,
                },
                "replayed": 0,
                "failed": 0,
                "skipped": len(pending),
                "aborted": False,
                "message": f"Dry run: canary passed, {len(pending)} entries would be replayed.",
            }

        # Step 2: Replay each entry
        replayed = 0
        failed = 0
        for entry in pending:
            entry.attempts += 1
            try:
                ok = self._deliver(entry)
                if ok:
                    entry.status = DLQEntryStatus.REPLAYED
                    entry.last_replay_at = datetime.now(timezone.utc).isoformat()
                    replayed += 1
                    logger.info(
                        "  ✓ Replayed entry %s → %s",
                        entry.entry_id, entry.target_node,
                    )
                else:
                    entry.status = DLQEntryStatus.REPLAY_FAILED
                    entry.last_replay_at = datetime.now(timezone.utc).isoformat()
                    failed += 1
                    logger.warning(
                        "  ✗ Replay failed for entry %s (attempt %d/%d)",
                        entry.entry_id, entry.attempts, entry.max_attempts,
                    )
            except Exception as e:
                entry.status = DLQEntryStatus.REPLAY_FAILED
                entry.last_replay_at = datetime.now(timezone.utc).isoformat()
                failed += 1
                logger.error("  ✗ Exception replaying %s: %s", entry.entry_id, e)

        # Clean up successfully replayed entries
        self.entries = [e for e in self.entries
                        if e.status != DLQEntryStatus.REPLAYED]
        self._save()

        return {
            "canary": {
                "success": True,
                "latency_ms": canary_result.latency_ms,
            },
            "replayed": replayed,
            "failed": failed,
            "skipped": 0,
            "aborted": False,
            "message": (
                f"Canary passed. Replayed {replayed}/{len(pending)} entries, "
                f"{failed} failed."
            ),
        }

    def _deliver(self, entry: DLQEntry) -> bool:
        """
        Simulate actual message delivery.
        In a real mesh, this would use the transport layer to resend
        entry.original_message to entry.target_node.
        """
        node_info = self.canary.node_registry.get(entry.target_node)
        if node_info is None or not node_info.get("online", False):
            return False
        # Simulate successful delivery (canary already validated the route)
        return True

    # -- Inspection --

    def status(self) -> dict:
        counts: dict[str, int] = {}
        for e in self.entries:
            counts[e.status.value] = counts.get(e.status.value, 0) + 1
        return {
            "total": len(self.entries),
            "by_status": counts,
            "entries": [e.to_dict() for e in self.entries],
        }


# ---------------------------------------------------------------------------
# CLI
# ---------------------------------------------------------------------------

def cmd_enqueue(args, dlq: DLQManager):
    """Enqueue a test message into the DLQ."""
    message = json.loads(args.message) if args.message else {
        "type": "test",
        "content": f"test-message-{uuid.uuid4().hex[:6]}",
    }
    dlq.enqueue(
        message=message,
        target_node=args.target,
        source_node=args.source or "runa",
        transport=args.transport or "websocket",
        failure_reason=args.reason or "delivery_timeout",
    )
    print(json.dumps({"status": "enqueued", "target": args.target}, indent=2))


def cmd_replay(args, dlq: DLQManager):
    """Perform canary-gated replay."""
    result = dlq.replay_with_canary(
        target_node=args.target,
        transport=args.transport,
        dry_run=args.dry_run,
    )
    print(json.dumps(result, indent=2))


def cmd_status(args, dlq: DLQManager):
    """Show DLQ status."""
    print(json.dumps(dlq.status(), indent=2, ensure_ascii=False))


def cmd_canary(args, dlq: DLQManager):
    """Send a standalone canary probe."""
    result = dlq.canary.send(args.target, args.transport or "websocket")
    print(json.dumps({
        "success": result.success,
        "latency_ms": result.latency_ms,
        "error": result.error,
        "response": result.response,
    }, indent=2))


def cmd_seed(args, dlq: DLQManager):
    """Seed the DLQ with sample entries for testing."""
    samples = [
        ("tor", "websocket", "connection_refused"),
        ("manon", "websocket", "ack_timeout"),
        ("kai", "websocket", "node_unreachable"),
    ]
    for target, transport, reason in samples:
        dlq.enqueue(
            message={
                "type": "agent_message",
                "content": f"seeded-message-for-{target}",
                "timestamp": datetime.now(timezone.utc).isoformat(),
            },
            target_node=target,
            source_node="runa",
            transport=transport,
            failure_reason=reason,
        )
    print(json.dumps({"status": "seeded", "count": len(samples)}, indent=2))


def cmd_clear(args, dlq: DLQManager):
    """Clear all DLQ entries."""
    count = len(dlq.entries)
    dlq.entries.clear()
    dlq._save()
    print(json.dumps({"status": "cleared", "removed": count}, indent=2))


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="dlq_canary",
        description="DLQ Canary-Gated Replay for A2A Mesh",
    )
    parser.add_argument(
        "--dlq-file",
        default="dlq.json",
        help="Path to the DLQ JSON file (default: dlq.json)",
    )
    sub = parser.add_subparsers(dest="command", required=True)

    # seed
    p_seed = sub.add_parser("seed", help="Seed DLQ with sample entries")
    p_seed.set_defaults(func=cmd_seed)

    # enqueue
    p_enq = sub.add_parser("enqueue", help="Enqueue a message into the DLQ")
    p_enq.add_argument("--target", required=True, help="Target node name")
    p_enq.add_argument("--source", default=None, help="Source node name")
    p_enq.add_argument("--transport", default=None, help="Transport type")
    p_enq.add_argument("--reason", default=None, help="Failure reason")
    p_enq.add_argument("--message", default=None, help="JSON message body")
    p_enq.set_defaults(func=cmd_enqueue)

    # replay
    p_rep = sub.add_parser("replay", help="Canary-gated DLQ replay")
    p_rep.add_argument("--target", default=None, help="Filter by target node")
    p_rep.add_argument("--transport", default=None, help="Filter by transport")
    p_rep.add_argument("--dry-run", action="store_true", help="Don't actually replay")
    p_rep.set_defaults(func=cmd_replay)

    # canary
    p_can = sub.add_parser("canary", help="Send a standalone canary probe")
    p_can.add_argument("--target", required=True, help="Target node name")
    p_can.add_argument("--transport", default=None, help="Transport type")
    p_can.set_defaults(func=cmd_canary)

    # status
    p_stat = sub.add_parser("status", help="Show DLQ status")
    p_stat.set_defaults(func=cmd_status)

    # clear
    p_clr = sub.add_parser("clear", help="Clear all DLQ entries")
    p_clr.set_defaults(func=cmd_clear)

    return parser


def main():
    parser = build_parser()
    args = parser.parse_args()

    dlq = DLQManager(dlq_path=args.dlq_file)
    args.func(args, dlq)


if __name__ == "__main__":
    main()